-- Isolated fixtures only: execute this entire file in one transaction, always rollback.
begin;
do $$
declare ids uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
 sessions uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
 u uuid;p uuid;a uuid;b uuid;n integer;checks integer:=0;denied boolean;s jsonb;t jsonb;c jsonb;bundle jsonb;media jsonb;original jsonb;linked jsonb;history jsonb;
 credentials text;keynotes text;identity text;limits jsonb;token text:='wsc_'||repeat('d',64);request uuid:=gen_random_uuid();archive_request uuid:=gen_random_uuid();args jsonb;archive_args jsonb;imported jsonb;
 doc jsonb:='{"type":"doc","attrs":{"schemaVersion":2},"content":[{"type":"paragraph","content":[{"type":"text","text":"Entrevista temporal"}]}]}';
 gateway text:='workspace-support-disposable-live-gateway';
begin
 select md5(coalesce(string_agg(id::text||coalesce(encrypted_password,''),'' order by id),'')) into credentials from auth.users;
 select md5(coalesce(string_agg(to_jsonb(k)::text,'' order by id),'')) into keynotes from public.gba_keynotes k;
 select md5(pg_get_functiondef(oid)) into identity from pg_proc where pronamespace='public'::regnamespace and proname='gba_id_gateway';
 select to_jsonb(l) into limits from workspace_private.original_limits l where singleton;
 for n in 1..5 loop
  insert into auth.users(id,email,aud,role,raw_user_meta_data,is_sso_user,is_anonymous,created_at,updated_at) values(ids[n],'support-live-'||ids[n]||'@example.invalid','authenticated','authenticated','{}',false,false,now(),now());
  insert into auth.sessions(id,user_id,created_at,updated_at) values(sessions[n],ids[n],now(),now());
 end loop;
 select id into u from public.workspace_units where slug='gimg';
 insert into public.workspace_unit_memberships(unit_id,user_id,membership_status) select u,x,'active' from unnest(ids)x;
 insert into public.workspace_access_grants(user_id,unit_id,access_role,scope_type,scope_id,reason) values(ids[1],u,'gimg_direction','unit',u,'Rollback support acceptance');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[1],'session_id',sessions[1],'role','authenticated')::text,true);perform set_config('role','authenticated',true);
 p:=(public.workspace_command('project.create',jsonb_build_object('unit_id',u,'title','Rollback support acceptance'))->>'id')::uuid;
 select id into a from public.workspace_areas where project_id=p and specialty='research';select id into b from public.workspace_areas where project_id=p and specialty='text';
 perform set_config('role','postgres',true);
 for n in 2..5 loop
  insert into public.workspace_access_grants(user_id,access_role,unit_id,scope_type,scope_id,granted_by,reason) values(ids[n],case when n=2 then 'gimg_area_lead' else 'gimg_contributor' end,u,'area',case when n=5 then b else a end,ids[1],'Rollback support acceptance');
  insert into public.workspace_assignments(user_id,assignment_role,unit_id,project_id,area_id,assigned_by) values(ids[n],'researcher',u,p,case when n=5 then b else a end,ids[1]);
 end loop;
 update workspace_private.original_limits set enabled=true,gateway_key_hash=encode(extensions.digest(gateway,'sha256'),'hex') where singleton;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[3],'session_id',sessions[3],'role','authenticated')::text,true);perform set_config('role','authenticated',true);
 s:=public.workspace_save_support(p,jsonb_build_object('title','Entrevista temporal','area_id',a,'document_kind','interview','content_document',doc,'editor_version',2,'credits','Fixture','palette',jsonb_build_array('#663399')),0);
 if s->>'share_scope'<>'private' or (select count(*) from public.workspace_deliverables where project_id=p)<>0 then raise exception 'Private support created a delivery';end if;checks:=checks+1;
 denied:=false;begin perform public.workspace_save_support(p,s||jsonb_build_object('area_id',b), (s->>'revision')::integer);exception when others then denied:=true;end;if not denied then raise exception 'Support moved to inaccessible area';end if;checks:=checks+1;
 denied:=false;begin perform public.workspace_save_support(p,s,0);exception when others then denied:=true;end;if not denied then raise exception 'Stale revision overwrote support';end if;checks:=checks+1;
 for n in 1..5 loop
  if n=3 then continue;end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[n],'session_id',sessions[n],'role','authenticated')::text,true);
  if jsonb_array_length(public.workspace_support_bundle(p)->'documents')<>0 then raise exception 'Private support leaked to actor %',n;end if;checks:=checks+1;
  denied:=false;begin perform public.workspace_support_history((s->>'id')::uuid);exception when others then denied:=true;end;if not denied then raise exception 'Private history leaked';end if;checks:=checks+1;
 end loop;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[3],'session_id',sessions[3],'role','authenticated')::text,true);
 media:=public.workspace_prepare_support_original((s->>'id')::uuid,'Entrevista.pdf');
 perform public.workspace_original_gate((media->>'id')::uuid,gateway);checks:=checks+1;
 original:=public.workspace_original_begin((media->>'id')::uuid,'Entrevista.pdf','application/pdf',8,repeat('e',64),gateway);
 perform public.workspace_original_finish((original->>'id')::uuid,true,gateway);
 if public.workspace_original_descriptor((original->>'id')::uuid)->>'mime_type'<>'application/pdf' then raise exception 'PDF support original failed';end if;checks:=checks+1;
 if exists(select 1 from jsonb_array_elements(public.workspace_reference_bundle(p)->'references')r where r->>'id'=media->>'id') then raise exception 'Private originals leaked into reference library';end if;checks:=checks+1;
 doc:=jsonb_build_object('type','doc','attrs',jsonb_build_object('schemaVersion',2),'content',jsonb_build_array(jsonb_build_object('type','paragraph','content',jsonb_build_array(jsonb_build_object('type','text','text','Entrevista temporal'),jsonb_build_object('type','mention','attrs',jsonb_build_object('id',ids[4],'label','Fixture','anchorId',gen_random_uuid()))))));
 s:=public.workspace_save_support(p,s||jsonb_build_object('content_document',doc,'editor_version',2),(s->>'revision')::integer);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[4],'session_id',sessions[4],'role','authenticated')::text,true);
 if exists(select 1 from jsonb_array_elements(public.workspace_notifications()->'items')x where x->>'support_id'=s->>'id') then raise exception 'Private mention notified outsider';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[3],'session_id',sessions[3],'role','authenticated')::text,true);
 s:=public.workspace_support_action((s->>'id')::uuid,'share','{"share_scope":"area"}',(s->>'revision')::integer);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[4],'session_id',sessions[4],'role','authenticated')::text,true);
 bundle:=public.workspace_support_bundle(p);
 if jsonb_array_length(bundle->'documents')<>1 or (bundle->'documents'->0->>'can_edit')::boolean then raise exception 'Area sharing permissions wrong';end if;checks:=checks+1;
 if not exists(select 1 from jsonb_array_elements(public.workspace_notifications()->'items')x where x->>'support_id'=s->>'id' and x->>'event_type'='support.mention') then raise exception 'Authorized mention missing';end if;checks:=checks+1;
 perform public.workspace_original_descriptor((original->>'id')::uuid);checks:=checks+1;
 denied:=false;begin perform public.workspace_save_support(p,s,(s->>'revision')::integer);exception when others then denied:=true;end;if not denied then raise exception 'Reader edited another author';end if;checks:=checks+1;
 denied:=false;begin perform public.workspace_original_gate((media->>'id')::uuid,gateway);exception when others then denied:=true;end;if not denied then raise exception 'Reader uploaded another author original';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[5],'session_id',sessions[5],'role','authenticated')::text,true);
 if jsonb_array_length(public.workspace_support_bundle(p)->'documents')<>0 then raise exception 'Support crossed areas';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[3],'session_id',sessions[3],'role','authenticated')::text,true);
 s:=public.workspace_support_action((s->>'id')::uuid,'share','{"share_scope":"private"}',(s->>'revision')::integer);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[4],'session_id',sessions[4],'role','authenticated')::text,true);
 if jsonb_array_length(public.workspace_support_bundle(p)->'documents')<>0 or exists(select 1 from jsonb_array_elements(public.workspace_notifications()->'items')x where x->>'support_id'=s->>'id') then raise exception 'Revoked share still visible';end if;checks:=checks+1;
 denied:=false;begin perform public.workspace_original_descriptor((original->>'id')::uuid);exception when others then denied:=true;end;if not denied then raise exception 'Revoked original still downloadable';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[2],'session_id',sessions[2],'role','authenticated')::text,true);
 t:=public.workspace_command('task.create',jsonb_build_object('project_id',p,'area_id',a,'title','Fuentes temporales','responsible_id',ids[3]));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[3],'session_id',sessions[3],'role','authenticated')::text,true);
 s:=public.workspace_support_action((s->>'id')::uuid,'link',jsonb_build_object('linked_task_id',t->>'id'),(s->>'revision')::integer);
 linked:=public.workspace_opal_bundle(p)->'task_references'->(t->>'id')->0;
 if linked->'snapshot'->'content_document'<>doc or jsonb_array_length(linked->'originals')<>1 then raise exception 'Frozen support link lost text or original';end if;checks:=checks+1;
 s:=public.workspace_save_support(p,s||jsonb_build_object('title','Entrevista corregida','editor_version',2),(s->>'revision')::integer);
 if public.workspace_opal_bundle(p)->'task_references'->(t->>'id')->0->'snapshot'->>'title'='Entrevista corregida' then raise exception 'Frozen link changed with source';end if;checks:=checks+1;
 c:=public.workspace_support_action((s->>'id')::uuid,'convert','{}',(s->>'revision')::integer);
 if c->>'state'<>'assigned' or (c->>'current_version')::integer<>0 or public.workspace_draft((c->>'id')::uuid)->'content_document'<>doc or jsonb_array_length(public.workspace_opal_bundle(p)->'task_references'->(c->>'id')->0->'originals')<>1 then raise exception 'Conversion submitted review or lost source';end if;checks:=checks+1;
 bundle:=public.workspace_team_bundle(p);
 if not exists(select 1 from jsonb_array_elements(bundle->'members')x where x->>'user_id'=ids[4]::text) or exists(select 1 from jsonb_array_elements(bundle->'members')x where x->>'user_id'=ids[5]::text) then raise exception 'Team area scope failed';end if;checks:=checks+1;
 history:=public.workspace_support_history((s->>'id')::uuid);if jsonb_array_length(history)<5 then raise exception 'Support history missing';end if;checks:=checks+1;
 denied:=false;begin perform count(*) from workspace_private.support_documents;exception when others then denied:=true;end;if not denied then raise exception 'Direct private table exposed';end if;checks:=checks+1;
 perform public.workspace_connector_register(encode(extensions.digest(token,'sha256'),'hex'),'Rollback support acceptance');
 args:=jsonb_build_object('project_id',p,'revision',0,'data',jsonb_build_object('title','Importación temporal','area_id',a,'document_kind','notes','content_document',doc,'editor_version',2));
 imported:=public.workspace_connector_call(token,'support.save',args,request);
 if public.workspace_connector_call(token,'support.save',args,request)->>'id'<>imported->>'id' then raise exception 'Connector duplicated import';end if;checks:=checks+1;
 denied:=false;begin perform public.workspace_connector_call(token,'support.save',args||jsonb_build_object('data',args->'data'||jsonb_build_object('title','Otro contenido')),request);exception when others then denied:=true;end;if not denied then raise exception 'Connector request key accepted changed content';end if;checks:=checks+1;
 archive_args:=jsonb_build_object('id',imported->>'id','action','archive','revision',imported->'revision');perform public.workspace_connector_call(token,'support.action',archive_args,archive_request);
 if public.workspace_connector_call(token,'support.action',archive_args,archive_request)->>'id'<>imported->>'id' then raise exception 'Archive retry failed';end if;checks:=checks+1;
 denied:=false;begin perform public.workspace_connector_call(token,'support.save',args,request);exception when others then denied:=true;end;if not denied then raise exception 'Archived connector payload replayed';end if;checks:=checks+1;
 s:=(public.workspace_support_bundle(p)->'documents')->0;perform public.workspace_support_action((s->>'id')::uuid,'archive','{}',(s->>'revision')::integer);
 if jsonb_array_length(public.workspace_support_bundle(p)->'documents')<>0 then raise exception 'Archived support remained listed';end if;checks:=checks+1;
 perform set_config('role','postgres',true);
 if credentials<>(select md5(coalesce(string_agg(id::text||coalesce(encrypted_password,''),'' order by id),'')) from auth.users where id<>all(ids)) or keynotes<>(select md5(coalesce(string_agg(to_jsonb(k)::text,'' order by id),'')) from public.gba_keynotes k) then raise exception 'Existing credentials/keynotes changed';end if;checks:=checks+1;
 if identity<>(select md5(pg_get_functiondef(oid)) from pg_proc where pronamespace='public'::regnamespace and proname='gba_id_gateway') then raise exception 'Identity gateway changed';end if;checks:=checks+1;
 if exists(select 1 from pg_proc f join pg_namespace ns on ns.oid=f.pronamespace where ns.nspname='workspace_private' and f.proname like 'support_%' and has_function_privilege('authenticated',f.oid,'EXECUTE')) then raise exception 'Private support helper exposed';end if;checks:=checks+1;
 if not (select bool_and(relrowsecurity) from pg_class where oid in('workspace_private.support_documents'::regclass,'workspace_private.support_history'::regclass,'workspace_private.support_media'::regclass)) then raise exception 'Support RLS disabled';end if;checks:=checks+1;
 perform set_config('workspace.support_live_result',jsonb_build_object('checks',checks,'privateCreation',true,'authorOnlyEditing',true,'scopedSharingRevocation',true,'frozenLinks',true,'originalAuthorization',true,'conversionPreservesSource',true,'teamScope',true,'mentionVisibility',true,'connectorIdempotency',true,'privateRpcDenials',true,'identityFingerprint',identity,'capacityBytes',limits->'capacity_bytes','credentialsPreserved',true,'keynotesPreserved',true,'rollbackRequired',true)::text,true);
end;$$;
select current_setting('workspace.support_live_result')::jsonb as support_live_acceptance;
rollback;
